// ==============================================================================
// 1. ADD CSS FOR VINFAST SHOWROOM (PULSING HEADLIGHTS & TURNTABLE GLOW)
// ==============================================================================
const vinfastCss = `
                /* --- HIỆU ỨNG VINFAST SHOWROOM DI SẢN PHỐ CỔ --- */
                @keyframes vinfast-drl-glow {
                    0%, 100% { opacity: 0.95; filter: drop-shadow(0 0 4px #67e8f9); }
                    50% { opacity: 1; filter: drop-shadow(0 0 9px #38bdf8); }
                }
                .animate-vinfast-drl {
                    animation: vinfast-drl-glow 3.5s ease-in-out infinite;
                }
                @keyframes vinfast-car-shimmer {
                    0%, 100% { transform: translateY(0); }
                    50% { transform: translateY(-0.8px); }
                }
                .animate-vinfast-car {
                    animation: vinfast-car-shimmer 4s ease-in-out infinite;
                }
`;

const styleClosingTag = '`}</style>';
if (code.includes(styleClosingTag) && !code.includes('animate-vinfast-drl')) {
  code = code.replace(styleClosingTag, vinfastCss + '\n            ' + styleClosingTag);
  console.log('Added VinFast showroom CSS keyframes!');
}

